import groovy.json.JsonSlurper
import org.gradle.api.provider.Property
import org.gradle.api.provider.ValueSource
import org.gradle.api.provider.ValueSourceParameters
import java.net.HttpURLConnection
import java.net.URI

/**
 * Fetches the body of an existing GitHub release, e.g. the notes generated by the release workflow.
 */
abstract class GitHubReleaseNotes : ValueSource<String, GitHubReleaseNotes.Parameters> {
    interface Parameters : ValueSourceParameters {
        val repository: Property<String>
        val tag: Property<String>
    }

    override fun obtain(): String {
        val repository = parameters.repository.get()
        val tag = parameters.tag.get()
        val url = "https://api.github.com/repos/$repository/releases/tags/$tag"

        val connection = URI(url).toURL().openConnection() as HttpURLConnection
        connection.setRequestProperty("Accept", "application/vnd.github+json")

        try {
            check(connection.responseCode == HttpURLConnection.HTTP_OK) {
                "Could not fetch GitHub release '$tag' of $repository (HTTP ${connection.responseCode}) - " +
                    "has the release workflow finished?"
            }

            val release = connection.inputStream.use { JsonSlurper().parse(it) } as Map<*, *>
            return release["body"] as? String ?: ""
        } finally {
            connection.disconnect()
        }
    }
}
